package com.autocare.platform.order;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;

/** Real MySQL issuance tests, including the inherited inventory/policy regressions. */
class JdbcInvitationRewardsTest extends JdbcInviteRewardPoliciesTest {
 InvitationRewards rewards;InvitationRegistration registration;
 @BeforeEach void rewards(){for(String t:List.of("invite_reward_item","invite_reward_batch","invite_registration","invite_code","invite_phone_evidence"))jdbc.update("DELETE FROM "+t);rewards=new InvitationRewards(db,coupons,true);registration=new InvitationRegistration(db,rewards);}
 String promo(String type){long id=type.equals("user")?1:2;jdbc.update("INSERT INTO invite_code(code,actor_type,actor_id,merchant_id,created_at) VALUES(?,?,?,?,?)","12345678901234567890123456789012",type,id,type.equals("user")?null:2,ReservationStore.time(clock.value));return "12345678901234567890123456789012";}
 long qualify(String code,String source,int n){long user=registration.register("synthetic-new-"+n,code,source,"test-app");registration.bindPhone(user,"1390000"+String.format("%04d",n),"test-app",true);return user;}
 long batch(long user){return jdbc.queryForObject("SELECT id FROM invite_reward_batch WHERE invitee_id=?",Long.class,user);}
 String state(long id){return jdbc.queryForObject("SELECT state FROM invite_reward_batch WHERE id=?",String.class,id);}
 long configured(int quantity,String scope){long c=rewardCoupon(quantity);activate(draft(c,scope));return c;}
 @Test void qualificationFreezesAndReadsNeverIssue(){long c=configured(4,"OWNER");long u=qualify(promo("user"),"VERIFIED_WECHAT",1),b=batch(u);assertEquals("READY",state(b));assertEquals(2,count("invite_reward_item"));assertEquals(0,count("coupon_issue"));assertEquals(1L,rewards.records(owner,1).get("total"));assertEquals(0,count("coupon_issue"));rewards.process(b);assertEquals("COMPLETE",state(b));assertEquals(2,count("coupon_issue"));assertEquals(2,count("coupon_stock_event"));assertEquals(2,jdbc.queryForObject("SELECT issued_quantity FROM coupon WHERE id=?",Integer.class,c));rewards.process(b);assertEquals(2,count("coupon_issue"));assertEquals("AVAILABLE",mineAvailability());}
 @Test void repeatTemplatesAcrossEventsAndPublicOnceAreIndependent(){long c=configured(8,"OWNER");String code=promo("user");rewards.process(batch(qualify(code,"VERIFIED_WECHAT",2)));rewards.process(batch(qualify(code,"VERIFIED_WECHAT",3)));assertEquals(2,jdbc.queryForObject("SELECT COUNT(*) FROM coupon_issue WHERE user_id=1 AND origin='INVITE'",Integer.class));assertEquals(1L,coupons.offers(owner,null,1,20).get("total"));coupons.claim(owner,key(),claimBody(c));assertEquals(409,code(()->coupons.claim(owner,key(),claimBody(c))));assertEquals(5,count("coupon_issue"));assertEquals(0L,coupons.offers(owner,null,1,20).get("total"));}
 @Test void priorPublicClaimDoesNotBlockRewardAndInviteeReadsOnlyOwnReceipt(){long c=configured(4,"OWNER");coupons.claim(owner,key(),claimBody(c));long u=qualify(promo("user"),"VERIFIED_WECHAT",16);rewards.process(batch(u));assertEquals(3,count("coupon_issue"));var a=new com.autocare.platform.vehicle.VehicleOwner(u,session(u,"user","OWNER","test-app",null),java.time.Instant.now().plusSeconds(600));var r=(Map<?,?>)((List<?>)rewards.records(a,1).get("items")).get(0);for(var obj:(List<?>)r.get("rewards")){var item=(Map<?,?>)obj;if(item.get("role").equals("INVITEE")){assertEquals(true,item.get("own"));assertNotNull(item.get("user_coupon_id"));}else{assertEquals(false,item.get("own"));assertNull(item.get("user_coupon_id"));}}jdbc.update("UPDATE auth_session SET revoked_at=UTC_TIMESTAMP() WHERE id=?",a.session());assertEquals(401,code(()->rewards.records(a,1)));}
 @Test void sourceStopPreventsNewIssuanceEvenForFrozenPolicy(){long c=configured(4,"OWNER"),b=batch(qualify(promo("user"),"VERIFIED_WECHAT",17));coupons.status(merchant,c,key(),statusBody(2,"STOPPED"));rewards.process(b);assertEquals("WAIT_SOURCE",state(b));assertEquals(0,count("coupon_issue"));}
 @Test void populatedMigrationReplayPreservesPublicClaimAndRewardEvidence()throws Exception{long c=configured(4,"OWNER");coupons.claim(owner,key(),claimBody(c));long b=batch(qualify(promo("user"),"VERIFIED_WECHAT",18));rewards.process(b);try(var connection=jdbc.getDataSource().getConnection()){org.springframework.jdbc.datasource.init.ScriptUtils.executeSqlScript(connection,new org.springframework.core.io.FileSystemResource(java.nio.file.Path.of("..","docs","sql","migrations","V042__invitation_reward_delivery.sql")));}assertEquals(3,count("coupon_issue"));assertEquals("COMPLETE",state(b));assertEquals(1,count("invite_reward_batch"));assertEquals(409,code(()->coupons.claim(owner,key(),claimBody(c))));}
 @Test void staffPromotionNeverAwardsStaffIdEvenWhenOwnerIdsOverlap(){configured(3,"STAFF");long u=qualify(promo("staff_account"),"VERIFIED_WECHAT",4),b=batch(u);rewards.process(b);assertEquals(1,count("coupon_issue"));assertEquals(u,jdbc.queryForObject("SELECT user_id FROM coupon_issue",Long.class));assertEquals(0L,rewards.records(owner,1).get("total"));assertEquals(1L,rewards.records(other,1).get("total"));var record=(Map<?,?>)((List<?>)rewards.records(other,1).get("items")).get(0);var item=(Map<?,?>)((List<?>)record.get("rewards")).get(0);assertNull(item.get("user_coupon_id"));assertEquals(false,item.get("own"));assertEquals(0L,rewards.records(merchant,1).get("total"));}
 @Test void missingPolicyStaysUnknownAfterLaterPublicationAndTestNeverRewards(){String code=promo("user");long u=qualify(code,"VERIFIED_WECHAT",5);assertEquals("UNKNOWN_POLICY",state(batch(u)));configured(4,"OWNER");rewards.process(batch(u));assertEquals(0,count("coupon_issue"));qualify(code,"TEST",6);qualify(code,"UNKNOWN",7);assertEquals(1,count("invite_reward_batch"));}
 @Test void insufficientSharedStockDoesNotPartiallyIssueAndRestoresOnRetry(){long c=configured(1,"OWNER"),b=batch(qualify(promo("user"),"VERIFIED_WECHAT",8));rewards.process(b);assertEquals("WAIT_STOCK",state(b));assertEquals(0,count("coupon_issue"));assertEquals(0,count("coupon_stock_event"));assertEquals(0,jdbc.queryForObject("SELECT issued_quantity FROM coupon WHERE id=?",Integer.class,c));/* Synthetic repair only: no stock mutation API is introduced. */jdbc.update("UPDATE coupon SET total_quantity=2 WHERE id=?",c);rewards.process(b);assertEquals("COMPLETE",state(b));assertEquals(2,count("coupon_issue"));}
 @Test void disabledAccountAndIssuerWaitAndOriginalExpiryTerminates(){configured(4,"OWNER");long b=batch(qualify(promo("user"),"VERIFIED_WECHAT",9));jdbc.update("UPDATE user SET status=0 WHERE id=1");rewards.process(b);assertEquals("WAIT_ACCOUNT",state(b));jdbc.update("UPDATE user SET status=1 WHERE id=1");jdbc.update("UPDATE merchant SET status=0 WHERE id=1");rewards.process(b);assertEquals("WAIT_SOURCE",state(b));jdbc.update("UPDATE merchant SET status=1 WHERE id=1");clock.value=clock.value.plusSeconds(3600);rewards.process(b);assertEquals("EXPIRED",state(b));assertEquals(0,count("coupon_issue"));}
 @Test void policyStopDoesNotChangeFrozenRewardAndPhoneReplayDoesNotDuplicate(){long c=configured(4,"OWNER");long u=qualify(promo("user"),"VERIFIED_WECHAT",10),b=batch(u);long p=jdbc.queryForObject("SELECT id FROM invite_reward_policy",Long.class);policies.status(operator,p,key(),json.createObjectNode().put("expected_revision",2).put("status","STOPPED"));registration.bindPhone(u,"13900000010","test-app",true);assertEquals(1,count("invite_reward_batch"));rewards.process(b);assertEquals("COMPLETE",state(b));assertEquals(2,jdbc.queryForObject("SELECT COUNT(*) FROM coupon_issue WHERE coupon_id=? AND publication_revision=2",Integer.class,c));}
 @Test void auditFailureRollsBackBothRewardsAndSweepPersistsRetry(){configured(4,"OWNER");long b=batch(qualify(promo("user"),"VERIFIED_WECHAT",11));jdbc.execute("CREATE TRIGGER fail_coupon_audit BEFORE INSERT ON audit_log FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='synthetic rollback'");assertThrows(org.springframework.dao.DataAccessException.class,()->rewards.process(b));assertEquals("READY",state(b));assertEquals(0,count("coupon_issue"));assertEquals(0,count("user_coupon"));assertEquals(0,count("coupon_stock_event"));rewards.sweep();assertEquals(1,jdbc.queryForObject("SELECT attempts FROM invite_reward_batch WHERE id=?",Integer.class,b));jdbc.execute("DROP TRIGGER fail_coupon_audit");clock.value=clock.value.plusSeconds(300);rewards.sweep();assertEquals("COMPLETE",state(b));}
 @Test void alteredQualificationEvidenceNeverIssues(){configured(4,"OWNER");long u=qualify(promo("user"),"VERIFIED_WECHAT",12),b=batch(u);jdbc.update("UPDATE invite_registration SET identity_source='TEST' WHERE user_id=?",u);rewards.process(b);assertEquals("INVALID_EVIDENCE",state(b));assertEquals(0,count("coupon_issue"));}
 @Test void twoWorkersCommitExactlyOnePair()throws Exception{configured(4,"OWNER");long b=batch(qualify(promo("user"),"VERIFIED_WECHAT",13));var pool=Executors.newFixedThreadPool(2);var start=new CountDownLatch(1);try{var fs=new ArrayList<Future<?>>();for(int i=0;i<2;i++)fs.add(pool.submit(()->{start.await();rewards.process(b);return null;}));start.countDown();for(var f:fs)f.get(30,TimeUnit.SECONDS);assertEquals("COMPLETE",state(b));assertEquals(2,count("coupon_issue"));assertEquals(2,count("coupon_stock_event"));}finally{pool.shutdownNow();}}
 @Test void disabledSweepDoesNotIssue(){configured(4,"OWNER");qualify(promo("user"),"VERIFIED_WECHAT",14);new InvitationRewards(db,coupons,false).sweep();assertEquals(0,count("coupon_issue"));}
 @Test void clockRegressionWaitsWithoutCompletingBeforeQualification(){configured(4,"OWNER");long b=batch(qualify(promo("user"),"VERIFIED_WECHAT",19));clock.value=clock.value.minusSeconds(1);rewards.process(b);assertEquals("READY",state(b));assertEquals(0,count("coupon_issue"));clock.value=clock.value.plusSeconds(301);rewards.sweep();assertEquals("COMPLETE",state(b));}
 @Test void sourceLockWaitingAcrossExpiryNeverIssuesExpiredPair()throws Exception{
  configured(4,"OWNER");long b=batch(qualify(promo("user"),"VERIFIED_WECHAT",20));var pool=Executors.newSingleThreadExecutor();var ready=new CountDownLatch(1);
  var observedJdbc=new org.springframework.jdbc.core.JdbcTemplate(jdbc.getDataSource()){
   @Override public List<Map<String,Object>> queryForList(String sql,Object... args){if(sql.startsWith("SELECT id FROM merchant WHERE id=? AND status=1"))ready.countDown();return super.queryForList(sql,args);}
  };
  var observedDb=new ReservationStore(observedJdbc,json,db.writes,clock,new org.springframework.jdbc.datasource.DataSourceTransactionManager(jdbc.getDataSource()));
  var worker=new InvitationRewards(observedDb,new CouponInventory(observedDb,coupons.operators),true);
  var monitorSource=new org.springframework.jdbc.datasource.DriverManagerDataSource(mysql.getJdbcUrl(),"root",mysql.getPassword());
  try(var connection=jdbc.getDataSource().getConnection();var monitor=monitorSource.getConnection()){
   var diagnostics=new org.springframework.jdbc.core.JdbcTemplate(new org.springframework.jdbc.datasource.SingleConnectionDataSource(monitor,true));
   connection.setAutoCommit(false);try(var statement=connection.createStatement()){statement.executeQuery("SELECT id FROM merchant WHERE id=1 FOR UPDATE").close();}
   var future=pool.submit(()->worker.process(b));assertTrue(ready.await(20,TimeUnit.SECONDS),"worker must reach issuer lock before observing its wait");boolean waiting=false;long until=System.nanoTime()+TimeUnit.SECONDS.toNanos(8);
   while(System.nanoTime()<until){if(diagnostics.queryForList("SELECT trx_state,trx_query FROM information_schema.innodb_trx").stream().anyMatch(r->"LOCK WAIT".equals(r.get("trx_state"))&&String.valueOf(r.get("trx_query")).contains("FROM merchant"))){waiting=true;break;}if(future.isDone()){future.get();break;}Thread.sleep(100);}
   assertTrue(waiting,()->"expected actual issuer lock wait; transactions="+diagnostics.queryForList("SELECT trx_state,trx_query FROM information_schema.innodb_trx"));clock.value=clock.value.plusSeconds(3600);connection.commit();future.get(20,TimeUnit.SECONDS);assertEquals("EXPIRED",state(b));assertEquals(0,count("coupon_issue"));assertEquals(0,count("coupon_stock_event"));
  }finally{pool.shutdownNow();}
 }
 @Test void qualificationSnapshotAuditFailureRollsBackPhoneAndEligibility(){configured(4,"OWNER");long u=registration.register("synthetic-fail",promo("user"),"VERIFIED_WECHAT","test-app");jdbc.execute("CREATE TRIGGER fail_coupon_audit BEFORE INSERT ON audit_log FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='synthetic rollback'");assertThrows(org.springframework.dao.DataAccessException.class,()->registration.bindPhone(u,"13900000015","test-app",true));assertEquals(0,count("invite_reward_batch"));assertEquals(0,count("invite_phone_evidence"));assertEquals("PENDING",jdbc.queryForObject("SELECT qualification_status FROM invite_registration WHERE user_id=?",String.class,u));assertNull(jdbc.queryForObject("SELECT phone FROM user WHERE id=?",String.class,u));}
}
